    if (maps & 1u)
        result.rgb = coatStrengthTexture.SampleLevel(textureSampler, maps & 4u ? uv1 : uv0, 0).gba;
    if (maps & 2u)
        result.a = coatRoughnessTexture.SampleLevel(textureSampler, maps & 8u ? uv1 : uv0, 0).a;
